-- 0093: MYP2 command terms lead each part (comma-free first word). Rewording only.
begin;
update questions set prompt = 'A class investigates a biased drawing pin. It is dropped 200 times and lands point-up 130 times. The experiment is repeated in larger trials.', prompt_doc = '{"type":"doc","content":[{"type":"paragraph","content":[{"type":"text","text":"A class investigates a biased drawing pin. It is dropped 200 times and lands point-up 130 times. The experiment is repeated in larger trials."}]},{"type":"assessDiagramBlock","attrs":{"spec":{"kind":"table","title":"Drawing pin experiment","columns":["Drops","50","100","200","400"],"rows":[["Point-up","34","63","130","…"],["Relative frequency","0.68","0.63","0.65","…"]]}}}]}'::jsonb, config = config || '{"parts":[{"id":"a","label":"(a)","prompt":"Write down the relative frequency of point-up after 200 drops, as a decimal.","kind":"numeric","points":0.5,"hints":["Relative frequency = frequency ÷ total trials.","Divide the point-up count by 200."],"strand":"B(i)","answer":0.65,"tolerance":0.005},{"id":"b","label":"(b)","prompt":"Estimate how many point-up landings you would expect in 1000 drops, using the 200-drop result.","kind":"numeric","points":0.5,"hints":["Scale the relative frequency up to 1000 drops.","Multiply your decimal from (a) by 1000."],"strand":"B(i)","answer":650,"tolerance":0},{"id":"c","label":"(c)","prompt":"Describe in one short phrase what happens to the relative frequencies as the number of drops increases.","kind":"text","points":1,"hints":["Compare 0.68, 0.63 and 0.65 — are they moving in one direction?","Decide whether the values hover around one number or keep drifting."],"strand":"B(ii)","accepted":["it settles","settles","it settles near 0.65","settles near 0.65","it becomes more stable"],"keywords":[["settles","stable","steady around"]],"minKeywordGroups":1},{"id":"d","label":"(d)","prompt":"Verify your rule: calculate the number of point-up landings you predict in 400 drops, using the settled relative frequency.","kind":"numeric","points":1,"hints":["Use the relative frequency from (a) as the settled value.","Multiply 400 by your decimal from (a)."],"strand":"B(iii)","answer":260,"tolerance":0}]}'::jsonb where organization_id = '0a400000-0000-4000-8000-000000000001' and config->>'source' = 'assess2-myp2b-criteria' and (config->>'question_number')::int = 13;
update questions set prompt = 'A family drives 420 km to visit relatives. Their car uses fuel at a rate of 7.5 litres per 100 km, and fuel costs $1.60 per litre.', prompt_doc = '{"type":"doc","content":[{"type":"paragraph","content":[{"type":"text","text":"A family drives 420 km to visit relatives. Their car uses fuel at a rate of 7.5 litres per 100 km, and fuel costs "},{"type":"text","text":"$1.60 per litre."}]},{"type":"assessDiagramBlock","attrs":{"spec":{"kind":"table","title":"Family road trip","columns":["Journey","420 km"],"rows":[["Fuel rate","7.5 L per 100 km"],["Fuel price","$1.60 per litre"]]}}}]}'::jsonb, config = config || '{"parts":[{"id":"a","label":"(a)","prompt":"Calculate the number of 100 km units in the 420 km journey.","kind":"numeric","points":0.5,"hints":["How many hundreds fit into 420?","Divide the distance by 100."],"strand":"D(i)","answer":4.2,"tolerance":0},{"id":"b","label":"(b)","prompt":"Calculate the litres of fuel needed.","kind":"numeric","points":1,"hints":["Multiply the rate by the number of 100 km units.","Use your answer to (a) with the litres per 100 km."],"strand":"D(ii)","answer":31.5,"tolerance":0.05,"unit":"litres"},{"id":"c","label":"(c)","prompt":"Calculate the cost of the fuel.","kind":"numeric","points":1,"hints":["Multiply litres by price per litre.","Use your litres from (b) and the price given."],"strand":"D(iii)","answer":50.4,"tolerance":0.05,"unit":"$"},{"id":"d","label":"(d)","prompt":"State in a few words why the real cost might not be exactly $50.40.","kind":"text","points":0.5,"hints":["Is a fuel-consumption rate exact in real driving?","Consider traffic, speed and driving conditions."],"strand":"D(iv)","accepted":["the rate is an average","rate varies with driving conditions","traffic and speed affect fuel use"],"keywords":[["average","vary","varies","traffic","conditions","speed","estimate"]],"minKeywordGroups":1}]}'::jsonb where organization_id = '0a400000-0000-4000-8000-000000000001' and config->>'source' = 'assess2-myp2b-criteria' and (config->>'question_number')::int = 25;
commit;
